#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);games=File.join(client,'assets/Games');compat=File.join(client,'assets/Common/Code/Runtime/CompatibilityApp');catalog=File.readlines(File.join(root,'server/Bootstrap/src/main/resources/game-catalog-528.tsv'),chomp:true).drop(1).map{|l|c=l.split("\t");[c[1].downcase,c[3],c[4]]}.to_h{|code,cat,fam|[code,{category:cat,family:fam}]};rows=Dir.glob(File.join(compat,'*')).select{|p|File.directory?(p)&&catalog.key?(File.basename(p).downcase)}.map do|p|code=File.basename(p).downcase;matches=Dir.glob(File.join(games,'**/*')).select{|f|File.basename(f).downcase.include?(code)};{code:code,expected:catalog[code],commonTs:Dir.glob(File.join(p,'**/*.ts')).length,gamesMatches:matches.map{|m|m.delete_prefix(client+'/')}}end;report={schemaVersion:1,gamesTs:Dir.glob(File.join(games,'**/*.ts')).length,compatibilityTs:Dir.glob(File.join(compat,'**/*.ts')).length,concreteGamesInCommon:rows,checks:{allConcreteGamesUnderGames:rows.empty?,categoryAlignment:rows.all?{|r|r[:gamesMatches].any?}},verdict:'blocked-game-code-placement'};out=File.join(root,'docs/generated/creal02-games-classification.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");puts "CREAL02 AUDITED: #{rows.length} concrete implementations remain outside Games"
